/**
 * @param {number[]} arr
 * @param {Function} fn
 * @return {number[]}
 */
var filter = function(arr, fn) {
    // Initialize the result array
    const result = [];

    // Iterate over all elements with their index
    for (let i = 0; i < arr.length; i++) {
        // If the filter function returns a truthy value, keep the element
        if (fn(arr[i], i)) {
            result.push(arr[i]);
        }
    }

    return result;
};
